// Every clip this run should render.
// Edit this list to change what gets produced - it is the only place
// you need to touch for a new episode.
// refs are addressed as <Picture 1>..<Picture N> in the prompt, in this order.

const ROOT = 'D:/Claude/In_Progress/Claude_ConfyUI';
const R = ROOT + '/reels/pre-targaryen/refs';

const style1 = R + '/ep01_style_plate_00001_.png';
const child1 = R + '/ep01_child_forest_v3_00001_.png';
const men1   = R + '/ep01_first_men_00001_.png';

const style2 = R + '/ep02_style_plate_00001_.png';
const other  = R + '/ep02_other_00001_.png';
const wight  = R + '/ep02_wight_00001_.png';
const hero   = R + '/ep02_last_hero_00001_.png';
const wall   = R + '/ep02_wall_00001_.png';

const jobs = [
  { name: 'ep01_clip07', seed: 107, width: 768, height: 1344, refs: [style1] },
  { name: 'ep01_clip08', seed: 108, width: 768, height: 1344, refs: [style1, child1, men1] },
  { name: 'ep02_clip01', seed: 201, width: 576, height: 1024, refs: [style2] },
  { name: 'ep02_clip02', seed: 202, width: 576, height: 1024, refs: [style2] },
  { name: 'ep02_clip03', seed: 203, width: 576, height: 1024, refs: [style2, other] },
  { name: 'ep02_clip04', seed: 204, width: 576, height: 1024, refs: [style2, wight] },
  { name: 'ep02_clip05', seed: 205, width: 576, height: 1024, refs: [style2, hero] },
  { name: 'ep02_clip06', seed: 206, width: 576, height: 1024, refs: [style2, hero, child1] },
  { name: 'ep02_clip07', seed: 207, width: 576, height: 1024, refs: [style2, wall] },
  { name: 'ep02_clip08', seed: 208, width: 576, height: 1024, refs: [style2, wall] }
];

return jobs.map(j => ({ json: {
  name: j.name,
  seed: j.seed,
  width: j.width,
  height: j.height,
  root: ROOT,
  prompt: ROOT + '/reels/pre-targaryen/prompts/' + j.name + '.txt',
  refArgs: j.refs.join(' '),
  attempt: 0
} }));
